import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.Ba39LDvt.js";const p=JSON.parse('{"title":"境外升学申请","description":"按研究方向规划 IC 领域 PhD 与 MS 申请，准备推荐信、语言成绩和有证据的研究陈述。","frontmatter":{"title":"境外升学申请","description":"按研究方向规划 IC 领域 PhD 与 MS 申请，准备推荐信、语言成绩和有证据的研究陈述。"},"headers":[],"relativePath":"career/abroad.md","filePath":"career/abroad.md","lastUpdated":1795525517000}'),h={name:"career/abroad.md"};function i(o,t,l,n,c,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="境外升学申请" tabindex="-1">境外升学申请 <a class="header-anchor" href="#境外升学申请" aria-label="Permalink to &quot;境外升学申请&quot;">​</a></h1><p>境外申请应从“希望接受什么训练”出发，而不是先收集学校排名。芯片领域的研究条件差别很大：有人依赖流片与测试平台，有人以架构模拟、系统软件或 EDA 算法为主。适合你的导师、课题和资助安排，比笼统的学校名次更重要。</p><h2 id="phd-与-ms-怎么选" tabindex="-1">PhD 与 MS 怎么选 <a class="header-anchor" href="#phd-与-ms-怎么选" aria-label="Permalink to &quot;PhD 与 MS 怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>PhD</th><th>MS / MSc</th></tr></thead><tbody><tr><td>主要训练</td><td>长期研究与独立提出问题</td><td>课程深化、工程训练，部分项目含研究论文</td></tr><tr><td>申请重点</td><td>研究匹配、持续经历、推荐信、研究潜力</td><td>课程基础、项目能力与项目要求；研究型也重匹配</td></tr><tr><td>时间与资金</td><td>通常时间更长，资助结构需逐项确认</td><td>项目长短和费用差异大，不能默认有奖学金</td></tr><tr><td>决策前要问</td><td>导师招生、指导模式、经费、毕业要求</td><td>是否 thesis、能否进组、实习规则、总成本</td></tr></tbody></table><p>不同国家和项目命名不同；不能把所有 MS 当成“就业项目”，也不能把所有 PhD 当成自动全奖。资助是否覆盖学费、生活费、保险和暑期，以及续资助条件，都应核对正式 offer。</p><h2 id="常见申请时间线" tabindex="-1">常见申请时间线 <a class="header-anchor" href="#常见申请时间线" aria-label="Permalink to &quot;常见申请时间线&quot;">​</a></h2><p>以下以次年秋季入学、主要申请窗口在当年秋冬的项目为例。欧洲岗位制博士、春季入学与部分地区的轮次安排可能完全不同。</p><table tabindex="0"><thead><tr><th>相对入学时间</th><th>常见任务</th></tr></thead><tbody><tr><td>提前 12–18 个月</td><td>选择方向，完成有深度的课程 / 科研项目，了解语言与考试要求</td></tr><tr><td>提前 9–12 个月</td><td>整理导师与项目清单，预约语言考试，和推荐人讨论申请</td></tr><tr><td>入学前一年的 8–10 月</td><td>阅读目标组近年论文，准备简历、研究陈述与成绩材料</td></tr><tr><td>约 10 月至次年 1 月</td><td>按各项目截止日期提交，确认推荐信与成绩送达</td></tr><tr><td>约 1–4 月</td><td>面试、沟通导师，比较资助和培养条件</td></tr><tr><td>确认后至入学</td><td>按要求办理学历证明、签证、住宿等事项</td></tr></tbody></table><p>截止时间要按项目官网和时区记录。语言送分、推荐信和成绩认证可能耗时，不要把“当天点提交”当作材料完整的保证。</p><h2 id="按-ic-方向找项目" tabindex="-1">按 IC 方向找项目 <a class="header-anchor" href="#按-ic-方向找项目" aria-label="Permalink to &quot;按 IC 方向找项目&quot;">​</a></h2><p>下面是可用于启动检索的代表性学校示例，不是排名、完整名单或当年招生承诺。最终要回到院系和导师主页确认研究主题、学生培养及开放名额。</p><table tabindex="0"><thead><tr><th>兴趣方向</th><th>可开始检索的学校示例</th><th>重点看什么</th></tr></thead><tbody><tr><td>模拟、混合信号与射频</td><td>UC Berkeley、Stanford、UCLA、TU Delft、KU Leuven</td><td>近期芯片实测工作、测试设备、流片与指导安排</td></tr><tr><td>数字 VLSI 与 AI 硬件</td><td>MIT、Stanford、UC Berkeley、Georgia Tech、ETH Zürich、EPFL</td><td>架构到电路的研究边界、工作负载、硬件实现证据</td></tr><tr><td>体系结构与系统</td><td>Michigan、UIUC、Carnegie Mellon、UC San Diego</td><td>具体导师方向，硬件与系统软件协同方式</td></tr><tr><td>EDA 与设计方法</td><td>UC San Diego、UT Austin、Michigan、UIUC、清华大学相关国际项目</td><td>物理设计、验证、逻辑综合或优化的具体分支</td></tr><tr><td>器件与光电子</td><td>MIT、Stanford、UC Berkeley、ETH Zürich、EPFL</td><td>洁净室、工艺平台、器件制备与表征能力</td></tr><tr><td>亚洲地区 IC 项目</td><td>香港科技大学、香港中文大学、新加坡国立大学、南洋理工大学</td><td>院系归属、导师和项目性质、资助及语言要求</td></tr></tbody></table><p>建立选校表时增加：导师近期是否仍做该方向、论文作者中的学生训练方式、项目费用、申请条件、截止日期和备选导师。不要用一篇多年前的代表作判断一个组今天的方向。</p><h2 id="套磁与推荐信" tabindex="-1">套磁与推荐信 <a class="header-anchor" href="#套磁与推荐信" aria-label="Permalink to &quot;套磁与推荐信&quot;">​</a></h2><p>联系导师的邮件应短而具体：介绍背景、点出读过的一篇工作、说明相关经历、询问研究或招生匹配，并附精炼简历。不要群发、不许诺无法完成的结果，也不要把一次积极回复理解为录取。部分项目不鼓励提前联系，先看规定。</p><p>推荐信最好来自真正了解你工作过程的人。提前沟通，提供简历、项目贡献、申请清单和截止日期，留足撰写时间。对方若不便推荐，尊重其决定。不要索取保密推荐信内容，也不要伪造推荐人身份或擅自代交。</p><h2 id="语言、考试与材料" tabindex="-1">语言、考试与材料 <a class="header-anchor" href="#语言、考试与材料" aria-label="Permalink to &quot;语言、考试与材料&quot;">​</a></h2><p>TOEFL / IELTS、GRE 是否要求及有效期按项目核查，不凭往年经验推断豁免。总分与单项要求、考试形式是否接受、成绩送达方式都可能不同。</p><p>研究陈述（Statement of Purpose，SOP）应围绕具体经历和问题展开，说明个人贡献与未来兴趣；避免把简历扩写成流水账。论文状态必须准确标注为已发表、已录用、在投或预印本。保密项目只描述被允许公开的部分。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a>分享境外申请经验，注明年份、地区、方向与项目类型，不披露推荐信、私人邮件或其他申请者信息；个案结果不等于录取保证。</p></div><h2 id="继续准备" tabindex="-1">继续准备 <a class="header-anchor" href="#继续准备" aria-label="Permalink to &quot;继续准备&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/research-guide/">本科科研入门</a>与<a href="/shanghaitech-ic-wiki-dev.github.io/research-guide/writing">学术写作</a>：积累能被推荐人和材料准确说明的研究证据。</li><li><a href="https://www.ets.org/" target="_blank" rel="noreferrer">ETS</a>与<a href="https://ielts.org/" target="_blank" rel="noreferrer">IELTS</a>：考试政策以官方及项目要求为准。</li></ul>',22)])])}const u=a(h,[["render",i]]);export{p as __pageData,u as default};
